"use client"

import * as React from "react"
import { Check } from "lucide-react"
import { Sheet } from "scrollsheet"

import { cn } from "@/lib/utils"

interface ToastMessage {
  title: string
  description: string
}

/**
 * Toasts are consumer state, not a library concept: a queue in useState,
 * `modal={false}` so the page stays interactive, and one sheet that stays
 * open while the queue drains. Swapping the message re-measures the
 * `content` detent, so height changes animate through the built-in morph.
 */
function useToastQueue(duration = 3200) {
  const [queue, setQueue] = React.useState<ToastMessage[]>([])
  const current = queue[0]

  React.useEffect(() => {
    if (current === undefined) return
    const timer = setTimeout(() => setQueue((q) => q.slice(1)), duration)
    return () => clearTimeout(timer)
  }, [current, duration])

  return {
    queue,
    push: (message: ToastMessage) => setQueue((q) => [...q, message]),
    dismiss: () => setQueue((q) => q.slice(1)),
    clear: () => setQueue([]),
  }
}

function ToastStack({
  queue,
  onDismiss,
  onClear,
  className,
}: {
  queue: ToastMessage[]
  onDismiss: () => void
  onClear: () => void
  className?: string
}) {
  const current = queue[0]

  return (
    <Sheet.Root
      modal={false}
      open={queue.length > 0}
      onOpenChange={(open) => {
        if (!open) onClear()
      }}
      detents={["content"]}
    >
      <Sheet.Content
        className={cn(
          "bg-background flex items-center gap-3 rounded-xl border p-3 shadow-lg",
          className
        )}
        aria-label="Notification"
      >
        <span className="bg-primary text-primary-foreground flex h-8 w-8 shrink-0 items-center justify-center rounded-full">
          <Check className="h-4 w-4" />
        </span>
        <div className="flex-1">
          <div className="text-sm font-medium">{current?.title}</div>
          <div className="text-muted-foreground text-xs">{current?.description}</div>
        </div>
        <button
          type="button"
          className="text-sm font-medium underline-offset-4 hover:underline"
          onClick={onDismiss}
        >
          Undo
        </button>
      </Sheet.Content>
    </Sheet.Root>
  )
}

export { ToastStack, useToastQueue, type ToastMessage }
